import{c as t,Q as e,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Wait","description":"","frontmatter":{},"headers":[{"level":1,"title":"Wait","slug":"wait"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/Wait-98.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/Wait-98.md"}'),l={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/Wait-98.md"};function i(p,a,c,r,d,o){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="wait" tabindex="-1">Wait <a class="header-anchor" href="#wait" aria-label="Permalink to &quot;Wait&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>阻塞AI Core，非<a href="./Iterate-99.html">细粒度通信</a>时，等待handleId对应的通信任务完成，<a href="./Iterate-99.html">细粒度通信</a>时，等待handleId对应的<a href="./../HCCL-Tiling侧接口/SetStepSize.html">步长</a>长度的子通信任务完成。handleId调用Wait接口的顺序，须和Prepare接口一致。该接口默认在所有核上工作，用户也可以在调用前通过<a href="./../../../基础API/系统变量访问/GetBlockIdx.html">GetBlockIdx</a>指定其在某一个核上运行。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline int32_t Wait(HcclHandle handleId)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>handleId</td><td>输入</td><td>对应通信任务的标识ID，只能使用Prepare原语接口的返回值。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;zh-cn_topic_0000001952464897_screen103142322514&quot;&gt;using HcclHandle = int8_t;&lt;/pre&gt;</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><ul><li>0，表示成功</li><li>-1，表示失败</li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>调用本接口前确保已调用过<a href="./InitV2.html">InitV2</a>和<a href="./SetCcTilingV2.html">SetCcTilingV2</a>接口。</li><li>入参handleId只能使用Prepare原语对应接口的返回值。</li><li>本接口在AIC核或者AIV核上调用必须与对应的Prepare接口的调用核保持一致。</li><li>非<a href="./Iterate-99.html">细粒度通信</a>时，本接口的调用次数应该与Prepare的repeat次数一致，<a href="./Iterate-99.html">细粒度通信</a>时，本接口的调用次数应该与通信任务的总步骤数/步长*Prepare的repeat次数一致。handleId调用Wait接口的顺序，必须和Prepare接口一致。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGISTER_TILING_DEFAULT(ReduceScatterCustomTilingData); //ReduceScatterCustomTilingData为对应算子头文件定义的结构体</span></span>
<span class="line"><span>GET_TILING_DATA_WITH_STRUCT(ReduceScatterCustomTilingData, tilingData, tilingGM);</span></span>
<span class="line"><span>Hccl hccl;</span></span>
<span class="line"><span>GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;();  // AscendC自定义算子kernel中，通过此方式获取HCCL context</span></span>
<span class="line"><span>__gm__ void *mc2InitTiling = (__gm__ void *)(&amp;tiling-&gt;mc2InitTiling);</span></span>
<span class="line"><span>__gm__ void *mc2CcTiling = (__gm__ void *)(&amp;(tiling-&gt;mc2CcTiling));</span></span>
<span class="line"><span>hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>auto ret = hccl.SetCcTilingV2(offsetof(ReduceScatterCustomTilingData, mc2CcTiling));</span></span>
<span class="line"><span>if (ret != HCCL_SUCCESS) {</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>if (AscendC::g_coreType == AIC) {</span></span>
<span class="line"><span>    HcclHandle handleId = hccl.ReduceScatter(sendBuf, recvBuf, 100, HcclDataType::HCCL_DATA_TYPE_INT8, HcclReduceOp::HCCL_REDUCE_SUM, 10);</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    for (uint8_t i=0; i&lt;10; i++) {</span></span>
<span class="line"><span>        hccl.Commit(handleId ); // 通知服务端可以执行上述的ReduceScatter任务</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    for (uint8_t i=0; i&lt;10; i++) {</span></span>
<span class="line"><span>        hccl.Wait(handleId); // 阻塞接口，需等待上述ReduceScatter任务执行完毕</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    hccl.Finalize(); // 后续无其他通信任务，通知服务端执行上述ReduceScatter任务之后即可退出</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,16)])])}const _=t(l,[["render",i]]);export{u as __pageData,_ as default};
